class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), CT=CF.country;
    SWD.page({active:'dom',lv:'BR',label:'Domicílios'});
    $('src').innerHTML=SWD.srcLine(['sit','dom']);
    const urb=u=>D.sit[u][0]/(D.sit[u][0]+D.sit[u][1])*100;
    const M={ppd:{n:'Pessoas por domicílio',sm:'Por domicílio',v:u=>D.dom[u][1],t:v=>SWD.num(v,2),col:'Pessoas'},urb:{n:'Moram em área urbana',sm:'Urbana',v:urb,t:v=>SWD.pct(v,1),col:'% urbana'}};
    const st={l:SWD.q.get('u')||'BR',m:'ppd',hov:null};
    $('place').innerHTML=`<option value="BR">${CT.name}</option>`+UF.slice().sort((a,b)=>SWD.name(a).localeCompare(SWD.name(b))).map(u=>`<option value="${u}">${SWD.name(u)}</option>`).join('');
    $('place').onchange=e=>{st.l=e.target.value;draw()};
    SWD.seg($('m'),Object.entries(M).map(([k,v])=>[k,v.n,v.sm]),st.m,k=>{st.m=k;draw()},'Medida');
    const rank=new SW2.Ranking($('rank'),{onHover:u=>{st.hov=u;draw()},onClick:u=>{st.l=u;draw()}}); rank.expanded=true;
    const draw=()=>{ const l=st.hov||st.l, m=M[st.m];
      $('place').value=st.l;
      SWD.cada100($('c100'),[{k:'u',n:'Área urbana',v:D.sit[l][0],c:'var(--r4)'},{k:'r',n:'Área rural',v:D.sit[l][1],c:'var(--c2)'}],{title:`Cada 100 pessoas em ${SWD.name(l)}`,aria:`Urbana e rural, cada 100 pessoas em ${SWD.name(l)}`});
      $('c100st').innerHTML=SWD.stamp('sit');
      $('card').innerHTML=`<div class="meta">Domicílios particulares ocupados</div><div class="row1"><div class="nm">${SWD.name(l)}</div><div class="big">${SWD.mi(D.dom[l][0])}</div></div>
        <div class="facts"><div class="fact"><span>Pessoas por domicílio</span><b>${SWD.num(D.dom[l][1],2)}</b></div><div class="fact"><span>${CT.name}</span><b>${SWD.num(D.dom.BR[1],2)}</b></div></div><div style="margin-top:4px">${SWD.stamp('dom')}</div>`;
      rank.render({rows:UF.map(u=>({uf:u,v:m.v(u),txt:m.t(m.v(u))})),sel:st.l,hov:st.hov,col:m.col,head:'Estado',plural:'estados'});
    };
    draw();
  }
  renderVals(){ return {}; }
}
